function Newsletter() {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [status, setStatus] = useState("");
  const onSubmit = (e) => {
    e.preventDefault();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setError("Please enter a valid email address.");
      setStatus("");
      return;
    }
    setError("");
    setStatus(`Thanks — we'll send the next drop to ${email}.`);
    setEmail("");
  };
  return (
    <section className="block" aria-labelledby="newsletter-title">
      <div className="container">
        <div className="newsletter">
          <div>
            <span className="eyebrow">Stay in the loop</span>
            <h2 id="newsletter-title">First access to drops &amp; member sales</h2>
            <p>Join 120,000+ members. Unsubscribe anytime.</p>
          </div>
          <form noValidate onSubmit={onSubmit} aria-describedby="newsletter-status">
            <div className="field">
              <label htmlFor="newsletter-email">Email address</label>
              <input
                type="email"
                id="newsletter-email"
                name="email"
                placeholder="you@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                aria-invalid={Boolean(error)}
                aria-describedby={error ? "newsletter-error newsletter-help" : "newsletter-help"}
                autoComplete="email"
              />
              <span id="newsletter-help" className="help">We respect your inbox. No spam, ever.</span>
              {error && <span id="newsletter-error" className="error" role="alert">{error}</span>}
            </div>
            <div className="submit-row">
              <button type="submit" className="btn btn-primary">Subscribe</button>
            </div>
          </form>
          <div
            id="newsletter-status"
            className="newsletter-status"
            role="status"
            aria-live="polite"
          >
            {status}
          </div>
        </div>
      </div>
    </section>
  );
}

function Footer() {
