  const [activeCat, setActiveCat] = useState("All");
  const visible = useMemo(
    () => activeCat === "All" ? PRODUCTS : PRODUCTS.filter((p) => p.cat === activeCat),
    [activeCat]
  );
  return (
    <section className="block" aria-labelledby="featured-title" id="shop">
      <div className="container">
        <div className="section-head">
          <div>
            <span className="eyebrow">Featured</span>
            <h2 id="featured-title">Best of the season</h2>
            <p>Curated picks from our editors — pieces designed to anchor a thoughtful winter wardrobe.</p>
          </div>
          <a className="head-link" href="#all-products">View all products →</a>
        </div>
        <div className="chip-row" role="group" aria-label="Filter by category">
          {CATEGORIES.map((cat) => (
            <button
              key={cat}
              type="button"
              className="chip"
              aria-pressed={activeCat === cat}
              onClick={() => setActiveCat(cat)}
            >
              {cat}
            </button>
          ))}
        </div>
        <div className="product-grid">
          {visible.map((p) => (
            <ProductCard
              key={p.id}
              product={p}
              isWishlisted={wishlist.has(p.id)}
              onWishlist={onWishlist}
              onAdd={onAdd}
            />
          ))}
        </div>
      </div>
    </section>
  );
}

function Countdown({ deadline }) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  const diff = Math.max(0, deadline - now);
  const h = Math.floor(diff / 3600000);
  const m = Math.floor((diff % 3600000) / 60000);
  const s = Math.floor((diff % 60000) / 1000);
  const pad = (n) => String(n).padStart(2, "0");
  return (
    <div
      className="countdown"
      role="timer"
      aria-live="off"
      aria-label={`Offer ends in ${h} hours ${m} minutes`}
    >
      <div><span className="v">{pad(h)}</span><span className="l">Hours</span></div>
      <div><span className="v">{pad(m)}</span><span className="l">Minutes</span></div>
      <div><span className="v">{pad(s)}</span><span className="l">Seconds</span></div>
    </div>
  );
}

function Deals() {
  const f = DEALS.featured;
  return (
    <section className="block" aria-labelledby="deals-title">
      <div className="container">
        <div className="section-head">
          <div>
            <span className="eyebrow">Deals</span>
            <h2 id="deals-title">Limited-time offers</h2>
            <p>Member drops and seasonal markdowns — reserve before they're gone.</p>
          </div>
        </div>
        <div className="deals-grid">
          <article className="deal-card deal-featured">
            <div className="bg" role="img" aria-label="Atmospheric studio shot of a winter capsule layout" style={{backgroundImage: `url(${f.img})`}} />
            <span className="eyebrow">{f.eyebrow}</span>
            <h3>{f.title}</h3>
            <p>{f.desc}</p>
            <Countdown deadline={f.deadline} />
            <div>
              <a className="btn btn-primary" href={f.href}>{f.cta} <Icon name="arrow" style={{width:16, height:16}} /></a>
            </div>
          </article>
          <div className="deal-stack">
            {DEALS.side.map((d, i) => (
              <article className="deal-card" key={i}>
                <div className="bg" role="img" aria-label={`Imagery for ${d.title}`} style={{backgroundImage: `url(${d.img})`}} />
                <span className="eyebrow">{d.eyebrow}</span>
                <h3>{d.title}</h3>
                <p>{d.desc}</p>
                <div>
                  <a className="btn btn-secondary" href={d.href}>{d.cta} →</a>
                </div>
              </article>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}

function Editorial() {
  return (
    <section className="block" aria-labelledby="editorial-title" id="journal">
      <div className="container">
        <div className="section-head">
          <div>
            <span className="eyebrow">The Journal</span>
            <h2 id="editorial-title">Stories &amp; style</h2>
            <p>Notes from our atelier on craft, sourcing, and how to wear our pieces.</p>
          </div>
          <a className="head-link" href="#all-articles">Read all stories →</a>
        </div>
        <div className="editorial-grid">
          {ARTICLES.map((a) => (
            <article className="editorial-card" key={a.id}>
              <a href={`#article-${a.id}`} className="media" aria-hidden="true" tabIndex="-1">
                <img src={a.img} alt="" loading="lazy" />
              </a>
              <div className="editorial-body">
                <div className="editorial-meta">
                  <span className="pill">{a.category}</span>
                  <span>{a.read}</span>
                </div>
                <h3><a href={`#article-${a.id}`}>{a.title}</a></h3>
                <p>{a.excerpt}</p>
                <div className="editorial-foot">
                  <span className="avatar" aria-hidden="true">{a.author[0]}</span>
                  <span>By {a.author}</span>
                </div>
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

function Newsletter() {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [status, setStatus] = useState("");
  const onSubmit = (e) => {
    e.preventDefault();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setError("Please enter a valid email address.");
      setStatus("");
      return;
    }
    setError("");
    setStatus(`Thanks — we'll send the next drop to ${email}.`);
    setEmail("");
  };
  return (
    <section className="block" aria-labelledby="newsletter-title">
      <div className="container">
        <div className="newsletter">
          <div>
            <span className="eyebrow">Stay in the loop</span>
            <h2 id="newsletter-title">First access to drops &amp; member sales</h2>
            <p>Join 120,000+ members. Unsubscribe anytime.</p>
          </div>
          <form noValidate onSubmit={onSubmit} aria-describedby="newsletter-status">
            <div className="field">
              <label htmlFor="newsletter-email">Email address</label>
              <input
                type="email"
                id="newsletter-email"
                name="email"
                placeholder="you@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                aria-invalid={Boolean(error)}
                aria-describedby={error ? "newsletter-error newsletter-help" : "newsletter-help"}
                autoComplete="email"
              />
              <span id="newsletter-help" className="help">We respect your inbox. No spam, ever.</span>
              {error && <span id="newsletter-error" className="error" role="alert">{error}</span>}
            </div>
            <div className="submit-row">
              <button type="submit" className="btn btn-primary">Subscribe</button>
            </div>
          </form>
          <div
            id="newsletter-status"
            className="newsletter-status"
            role="status"
            aria-live="polite"
          >
            {status}
          </div>
        </div>
      </div>
    </section>
  );
}

function Footer() {
  const cols = [
    { h: "Shop", links: ["New arrivals", "Bestsellers", "Outerwear", "Knitwear", "Accessories"] },
    { h: "Help", links: ["Shipping", "Returns", "Size guide", "Contact us", "FAQ"] },
    { h: "Company", links: ["About", "Sustainability", "Stores", "Careers", "Press"] },
  ];
  return (
    <footer className="site-footer">
      <div className="container">
        <div className="footer-grid">
          <div className="about">
            <a href="#home" className="brand" aria-label="Northwind home" style={{marginBottom: 16}}>
              <span className="brand-mark" aria-hidden="true">N</span>
              <span>NORTHWIND</span>
            </a>
            <p>Quiet, considered essentials made by small ateliers across Europe. Designed in Copenhagen since 2014.</p>
          </div>
          {cols.map((col) => (
            <nav key={col.h} aria-label={col.h}>
              <h4>{col.h}</h4>
              <ul>{col.links.map((l) => <li key={l}><a href={`#${l.toLowerCase().replace(/\s+/g, "-")}`}>{l}</a></li>)}</ul>
            </nav>
          ))}
        </div>
        <div className="footer-bottom">
          <span>© 2026 Northwind Atelier. All rights reserved.</span>
          <ul className="socials" aria-label="Social media">
            <li><a href="#twitter" aria-label="Northwind on Twitter"><Icon name="twitter" /></a></li>
            <li><a href="#instagram" aria-label="Northwind on Instagram"><Icon name="instagram" /></a></li>
            <li><a href="#youtube" aria-label="Northwind on YouTube"><Icon name="youtube" /></a></li>
          </ul>
        </div>
      </div>
    </footer>
  );
}

function App() {
  const [wishlist, setWishlist] = useState(new Set());
  const [cart, setCart] = useState([]);
  const [toast, setToast] = useState("");
  const toastTimer = useRef(null);

  const onWishlist = (id) => {
    setWishlist((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };
  const onAdd = (id) => {
    setCart((c) => [...c, id]);
    const product = PRODUCTS.find((p) => p.id === id);
    setToast(`Added "${product.name}" to cart.`);
    clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(""), 3000);
  };

  return (
    <>
      <a className="skip-link" href="#main">Skip to main content</a>
      <PromoBar />
      <Header cartCount={cart.length} />
      <main id="main">
        <Hero />
        <FeaturedProducts wishlist={wishlist} onWishlist={onWishlist} onAdd={onAdd} />
        <Deals />
        <Editorial />
        <Newsletter />
      </main>
      <Footer />
      <div
        role="status"
        aria-live="polite"
        style={{
          position: "fixed", bottom: 24, left: "50%", transform: "translateX(-50%)",
          background: "#1b1f26", border: "1px solid #3a414d", color: "#fff",
          padding: toast ? "12px 18px" : 0, borderRadius: 10,
          opacity: toast ? 1 : 0, pointerEvents: "none",
          transition: "opacity .2s ease", zIndex: 100,
          fontSize: "0.9rem", fontWeight: 600,
          maxWidth: "90vw",
        }}
      >
        {toast}
      </div>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

