    var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 56px;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 36px;
  align-items: center;
}
.newsletter h2 {
  font-size: clamp(1.5rem, 2.5vw, 2.25rem);
  margin: 0 0 12px;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.newsletter p { color: var(--text-muted); margin: 0; }
.newsletter form {
