}
.newsletter .submit-row {
  display: flex; align-items: end; gap: 8px;
}
.newsletter-status {
  font-size: 0.9rem;
  margin-top: 12px;
  color: var(--success);
  font-weight: 600;
  min-height: 1.5em;
}

/* Footer */
.site-footer {
  padding: 64px 0 24px;
  background: #07090b;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 36px;
  margin-bottom: 48px;
}
.footer-grid h4 {
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text-dim);
  margin: 0 0 16px;
}
.footer-grid ul {
  list-style: none;
  margin: 0; padding: 0;
  display: flex; flex-direction: column; gap: 10px;
}
.footer-grid a {
  text-decoration: none;
  color: var(--text-muted);
  font-size: 0.95rem;
}
.footer-grid a:hover { color: var(--text); }
.footer-grid .about p {
  color: var(--text-muted);
  font-size: 0.95rem;
  max-width: 36ch;
}
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 24px;
  display: flex; justify-content: space-between;
  flex-wrap: wrap; gap: 16px;
  color: var(--text-dim);
  font-size: 0.85rem;
}
.socials {
  display: flex; gap: 8px;
}
.socials a {
  width: 36px; height: 36px;
  border-radius: 50%;
  border: 1px solid var(--border-strong);
  display: grid; place-items: center;
  color: var(--text-muted);
}
.socials a:hover { color: var(--text); border-color: var(--text-dim); }
.socials svg { width: 16px; height: 16px; }

/* Responsive */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .editorial-grid { grid-template-columns: repeat(2, 1fr); }
  .hero-inner { grid-template-columns: 1fr; gap: 36px; padding: 56px 24px 64px; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-featured { min-height: 360px; }
  .newsletter { grid-template-columns: 1fr; padding: 40px; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 720px) {
  .primary-nav { display: none; }
  .primary-nav.open {
    display: block;
    position: absolute;
    top: 100%; left: 0; right: 0;
    background: var(--bg-elev);
    border-bottom: 1px solid var(--border);
