}
.primary-nav a:hover {
  color: var(--text);
  background: var(--bg-elev);
}
.primary-nav a[aria-current="page"] {
  color: var(--text);
  background: var(--bg-elev);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}
.icon-btn {
  appearance: none;
  background: transparent;
  border: 1px solid transparent;
  color: var(--text);
  width: 40px; height: 40px;
  border-radius: 10px;
  display: inline-grid; place-items: center;
  cursor: pointer;
  position: relative;
}
.icon-btn:hover { background: var(--bg-elev); border-color: var(--border); }
.icon-btn svg { width: 20px; height: 20px; }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 0.7rem;
  font-weight: 800;
  min-width: 18px; height: 18px;
  border-radius: 9px;
  padding: 0 5px;
  display: inline-grid; place-items: center;
}

.mobile-toggle { display: none; }

/* Hero */
.hero {
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(1000px 500px at 90% -10%, rgba(255, 179, 71, 0.18), transparent 60%),
    radial-gradient(800px 400px at -10% 110%, rgba(138, 180, 255, 0.12), transparent 60%),
    var(--bg);
  border-bottom: 1px solid var(--border);
}
.hero-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 80px 24px 96px;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 56px;
  align-items: center;
}
.eyebrow {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent-strong);
  background: rgba(255, 179, 71, 0.1);
  padding: 6px 12px;
  border-radius: 999px;
  border: 1px solid rgba(255, 179, 71, 0.25);
}
.hero h1 {
  font-size: clamp(2.25rem, 5vw, 4rem);
  line-height: 1.05;
  letter-spacing: -0.02em;
  margin: 20px 0 16px;
  font-weight: 800;
}
.hero h1 .accent { color: var(--accent-strong); font-style: italic; font-weight: 800; }
.hero p.lead {
  color: var(--text-muted);
  font-size: 1.125rem;
  max-width: 52ch;
  margin: 0 0 32px;
}
.hero-ctas {
  display: flex; gap: 12px; flex-wrap: wrap;
}
.btn {
  appearance: none;
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 14px 22px;
  font-weight: 700;
  font-size: 0.95rem;
  cursor: pointer;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: inherit;
}
.btn-primary {
  background: var(--accent);
