  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.editorial-meta .pill {
  background: rgba(255, 179, 71, 0.12);
  color: var(--accent-strong);
  padding: 3px 9px;
  border-radius: 999px;
  font-weight: 700;
}
.editorial-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin: 0;
  letter-spacing: -0.01em;
}
.editorial-card h3 a {
  text-decoration: none;
  color: var(--text);
}
.editorial-card h3 a:hover { color: var(--accent-strong); }
.editorial-card p {
  color: var(--text-muted);
  margin: 0;
  font-size: 0.95rem;
}
.editorial-foot {
  margin-top: auto;
  padding-top: 16px;
  display: flex; align-items: center; gap: 10px;
  font-size: 0.85rem;
  color: var(--text-muted);
}
.avatar {
