  color-scheme: dark;
  --bg: #0b0d10;
  --bg-elev: #14171c;
  --bg-elev-2: #1b1f26;
  --border: #2a2f38;
  --border-strong: #3a414d;
  --text: #f1f3f6;
  --text-muted: #a3acba;
  --text-dim: #7b8696;
