  color-scheme: dark;
  --bg: #0b0d10;
  --bg-elev: #14171c;
  --bg-elev-2: #1b1f26;
  --border: #2a2f38;
  --border-strong: #3a414d;
  --text: #f1f3f6;
  --text-muted: #a3acba;
  --text-dim: #7b8696;
  --accent: #ffb347;
  --accent-strong: #ffc168;
  --accent-ink: #1a1205;
  --danger: #ef4444;
  --danger-strong: #dc2626;
  --success: #4ade80;
  --focus: #8ab4ff;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow: 0 8px 30px rgba(0, 0, 0, 0.45);
  --maxw: 1240px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }

a { color: inherit; }

/* Focus */
:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100px;
  left: 16px;
  background: var(--accent);
  color: var(--accent-ink);
  padding: 10px 16px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  z-index: 1000;
  text-decoration: none;
}
.skip-link:focus {
  top: 12px;
}

/* Layout */
.container {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 24px;
}

/* Top promo bar */
.promo-bar {
  background: linear-gradient(90deg, #1a1208, #2a1d0a);
  color: var(--accent-strong);
  text-align: center;
  font-size: 0.875rem;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border);
  letter-spacing: 0.02em;
}
.promo-bar strong { color: #fff; }

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(11, 13, 16, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  display: flex;
  align-items: center;
  gap: 32px;
  padding: 16px 24px;
  max-width: var(--maxw);
  margin: 0 auto;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  font-size: 1.25rem;
  letter-spacing: 0.06em;
  text-decoration: none;
  color: var(--text);
}
.brand-mark {
  width: 32px; height: 32px;
  display: inline-grid; place-items: center;
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 8px;
  font-weight: 900;
}

.primary-nav {
  flex: 1;
}
.primary-nav ul {
  display: flex;
  gap: 6px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.primary-nav a {
  display: inline-block;
  padding: 8px 14px;
  border-radius: 8px;
  text-decoration: none;
  color: var(--text-muted);
  font-weight: 500;
  font-size: 0.95rem;
}
.primary-nav a:hover {
  color: var(--text);
  background: var(--bg-elev);
}
.primary-nav a[aria-current="page"] {
  color: var(--text);
  background: var(--bg-elev);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}
.icon-btn {
  appearance: none;
  background: transparent;
  border: 1px solid transparent;
  color: var(--text);
  width: 40px; height: 40px;
  border-radius: 10px;
  display: inline-grid; place-items: center;
  cursor: pointer;
  position: relative;
}
.icon-btn:hover { background: var(--bg-elev); border-color: var(--border); }
.icon-btn svg { width: 20px; height: 20px; }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 0.7rem;
  font-weight: 800;
  min-width: 18px; height: 18px;
  border-radius: 9px;
  padding: 0 5px;
  display: inline-grid; place-items: center;
}

.mobile-toggle { display: none; }

/* Hero */
.hero {
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(1000px 500px at 90% -10%, rgba(255, 179, 71, 0.18), transparent 60%),
    radial-gradient(800px 400px at -10% 110%, rgba(138, 180, 255, 0.12), transparent 60%),
    var(--bg);
  border-bottom: 1px solid var(--border);
}
.hero-inner {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 80px 24px 96px;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 56px;
  align-items: center;
}
.eyebrow {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent-strong);
  background: rgba(255, 179, 71, 0.1);
  padding: 6px 12px;
  border-radius: 999px;
  border: 1px solid rgba(255, 179, 71, 0.25);
}
.hero h1 {
  font-size: clamp(2.25rem, 5vw, 4rem);
  line-height: 1.05;
  letter-spacing: -0.02em;
  margin: 20px 0 16px;
  font-weight: 800;
}
.hero h1 .accent { color: var(--accent-strong); font-style: italic; font-weight: 800; }
.hero p.lead {
  color: var(--text-muted);
  font-size: 1.125rem;
  max-width: 52ch;
  margin: 0 0 32px;
}
.hero-ctas {
  display: flex; gap: 12px; flex-wrap: wrap;
}
.btn {
  appearance: none;
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 14px 22px;
  font-weight: 700;
  font-size: 0.95rem;
  cursor: pointer;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: inherit;
}
.btn-primary {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn-primary:hover { background: var(--accent-strong); }
.btn-secondary {
  background: transparent;
  color: var(--text);
  border-color: var(--border-strong);
}
.btn-secondary:hover { background: var(--bg-elev); border-color: var(--text-dim); }

.hero-stats {
  display: flex;
  gap: 36px;
  margin-top: 48px;
  padding-top: 28px;
  border-top: 1px solid var(--border);
}
.hero-stats div { min-width: 0; }
.hero-stats .num {
  font-size: 1.75rem; font-weight: 800; color: var(--text);
  letter-spacing: -0.02em;
}
.hero-stats .lbl {
  font-size: 0.85rem; color: var(--text-dim);
  text-transform: uppercase; letter-spacing: 0.1em;
}

.hero-art {
  position: relative;
  aspect-ratio: 4/5;
  border-radius: 24px;
  overflow: hidden;
  background: linear-gradient(135deg, #1f2530, #0f1216);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
}
.hero-art img {
  width: 100%; height: 100%; object-fit: cover;
}
.hero-badge {
  position: absolute;
  bottom: 20px; left: 20px;
  background: rgba(11, 13, 16, 0.75);
  backdrop-filter: blur(10px);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius);
  padding: 14px 16px;
  display: flex; gap: 12px; align-items: center;
  max-width: 80%;
}
.hero-badge .dot { width: 10px; height: 10px; background: var(--success); border-radius: 50%; box-shadow: 0 0 10px var(--success); }
.hero-badge strong { display: block; font-size: 0.95rem; }
.hero-badge span { color: var(--text-muted); font-size: 0.8rem; }

/* Section */
section.block {
  padding: 80px 0;
  border-bottom: 1px solid var(--border);
}
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 36px;
  flex-wrap: wrap;
}
.section-head h2 {
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  margin: 8px 0 0;
}
.section-head p {
  color: var(--text-muted);
  margin: 0;
  max-width: 50ch;
}
.section-head .head-link {
  color: var(--accent-strong);
  text-decoration: none;
  font-weight: 600;
  font-size: 0.95rem;
  white-space: nowrap;
}
.section-head .head-link:hover { text-decoration: underline; }

/* Category chips */
.chip-row {
  display: flex; gap: 10px; flex-wrap: wrap;
  margin-bottom: 28px;
}
.chip {
  appearance: none;
  background: var(--bg-elev);
  color: var(--text-muted);
  border: 1px solid var(--border);
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
}
.chip:hover { color: var(--text); border-color: var(--border-strong); }
.chip[aria-pressed="true"] {
  background: var(--accent);
  color: var(--accent-ink);
  border-color: var(--accent);
}

/* Product grid */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.product-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform 0.2s ease, border-color 0.2s ease;
}
.product-card:hover {
  transform: translateY(-3px);
  border-color: var(--border-strong);
}
.product-media {
  position: relative;
  aspect-ratio: 1/1;
  background: #0f1216;
  overflow: hidden;
}
.product-media img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform 0.5s ease;
}
.product-card:hover .product-media img { transform: scale(1.05); }
.tag {
  position: absolute; top: 12px; left: 12px;
  font-size: 0.7rem; font-weight: 800;
  text-transform: uppercase; letter-spacing: 0.08em;
  padding: 5px 9px; border-radius: 6px;
  background: var(--bg);
  color: var(--text);
  border: 1px solid var(--border-strong);
}
.tag.sale { background: #b91c1c; color: #fff; border-color: #b91c1c; }
.tag.new { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
.wishlist-btn {
  position: absolute; top: 10px; right: 10px;
  width: 36px; height: 36px;
  border-radius: 50%;
  border: 1px solid var(--border-strong);
  background: rgba(11, 13, 16, 0.7);
  color: var(--text);
  cursor: pointer;
  display: grid; place-items: center;
  backdrop-filter: blur(6px);
}
.wishlist-btn:hover { color: var(--accent); }
.wishlist-btn[aria-pressed="true"] { color: var(--accent); border-color: var(--accent); }
.wishlist-btn svg { width: 18px; height: 18px; }

.product-body {
  padding: 16px;
  display: flex; flex-direction: column; gap: 6px;
  flex: 1;
}
.product-cat {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-dim);
}
.product-name {
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
  color: var(--text);
}
.product-name a {
  text-decoration: none;
  color: inherit;
}
.product-name a:hover { color: var(--accent-strong); }
.product-rating {
  display: flex; align-items: center; gap: 6px;
  font-size: 0.85rem;
  color: var(--text-muted);
}
.stars { color: var(--accent); letter-spacing: 1px; }
.product-foot {
  display: flex; align-items: center; justify-content: space-between;
  margin-top: auto;
  padding-top: 12px;
}
.price {
  display: flex; align-items: baseline; gap: 8px;
}
.price .now { font-weight: 800; font-size: 1.1rem; }
.price .was {
  color: var(--text-dim);
  text-decoration: line-through;
  font-size: 0.9rem;
}
.add-btn {
  appearance: none;
  background: var(--bg-elev-2);
  border: 1px solid var(--border-strong);
  color: var(--text);
  width: 36px; height: 36px;
  border-radius: 8px;
  cursor: pointer;
  display: grid; place-items: center;
  font-family: inherit;
}
.add-btn:hover {
  background: var(--accent);
  color: var(--accent-ink);
  border-color: var(--accent);
}
.add-btn svg { width: 18px; height: 18px; }

/* Deals */
.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 24px;
}
.deal-card {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--border);
  min-height: 320px;
  display: flex; flex-direction: column;
  justify-content: flex-end;
  padding: 32px;
  isolation: isolate;
  background: var(--bg-elev);
}
.deal-card .bg {
  position: absolute; inset: 0; z-index: -2;
  background-size: cover; background-position: center;
}
.deal-card::after {
  content: "";
  position: absolute; inset: 0; z-index: -1;
  background: linear-gradient(180deg, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.85) 100%);
}
.deal-featured { min-height: 460px; }
.deal-card .eyebrow { background: rgba(11,13,16,0.6); color: var(--accent-strong); border-color: rgba(255,179,71,0.4); }
.deal-card h3 {
  font-size: clamp(1.5rem, 2.5vw, 2.25rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  margin: 12px 0 8px;
  max-width: 22ch;
}
.deal-card p {
  color: var(--text-muted);
  margin: 0 0 20px;
  max-width: 40ch;
}
.deal-stack {
  display: flex; flex-direction: column; gap: 24px;
}
.deal-stack .deal-card { min-height: 218px; padding: 24px; }
.deal-stack .deal-card h3 { font-size: 1.35rem; }

/* Countdown */
.countdown {
  display: flex; gap: 10px;
  margin-bottom: 20px;
}
.countdown div {
  background: rgba(11,13,16,0.7);
  border: 1px solid var(--border-strong);
  border-radius: 10px;
  padding: 8px 12px;
  min-width: 60px;
  text-align: center;
}
.countdown .v {
  display: block;
  font-weight: 800; font-size: 1.25rem;
  font-variant-numeric: tabular-nums;
}
.countdown .l {
  display: block;
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-dim);
}

/* Editorial */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.editorial-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
}
.editorial-card .media {
  aspect-ratio: 16/10;
  overflow: hidden;
  background: #0f1216;
}
.editorial-card .media img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform 0.5s ease;
}
.editorial-card:hover .media img { transform: scale(1.04); }
.editorial-body {
  padding: 24px;
  display: flex; flex-direction: column; gap: 10px;
  flex: 1;
}
.editorial-meta {
  display: flex; gap: 10px; align-items: center;
  font-size: 0.8rem;
  color: var(--text-dim);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.editorial-meta .pill {
  background: rgba(255, 179, 71, 0.12);
  color: var(--accent-strong);
  padding: 3px 9px;
  border-radius: 999px;
  font-weight: 700;
}
.editorial-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin: 0;
  letter-spacing: -0.01em;
}
.editorial-card h3 a {
  text-decoration: none;
  color: var(--text);
}
.editorial-card h3 a:hover { color: var(--accent-strong); }
.editorial-card p {
  color: var(--text-muted);
  margin: 0;
  font-size: 0.95rem;
}
.editorial-foot {
  margin-top: auto;
  padding-top: 16px;
  display: flex; align-items: center; gap: 10px;
  font-size: 0.85rem;
  color: var(--text-muted);
}
.avatar {
  width: 32px; height: 32px;
  border-radius: 50%;
  background: var(--bg-elev-2);
  display: grid; place-items: center;
  font-weight: 700;
  color: var(--text);
  font-size: 0.85rem;
  border: 1px solid var(--border-strong);
}

/* Newsletter */
.newsletter {
  background:
    radial-gradient(600px 300px at 80% 50%, rgba(255,179,71,0.18), transparent 70%),
    var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 56px;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 36px;
  align-items: center;
}
.newsletter h2 {
  font-size: clamp(1.5rem, 2.5vw, 2.25rem);
  margin: 0 0 12px;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.newsletter p { color: var(--text-muted); margin: 0; }
.newsletter form {
  display: flex; gap: 8px; flex-wrap: wrap;
}
.field {
  flex: 1;
  min-width: 200px;
  display: flex; flex-direction: column; gap: 6px;
}
.field label {
  font-size: 0.85rem;
  color: var(--text-muted);
  font-weight: 600;
}
.field .visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0);
  white-space: nowrap; border: 0;
}
.field input[type="email"] {
  background: var(--bg);
  border: 1px solid var(--border-strong);
  border-radius: 10px;
  color: var(--text);
  padding: 14px 16px;
  font-size: 1rem;
  font-family: inherit;
  width: 100%;
}
.field input[type="email"]:focus {
  outline: none;
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(138, 180, 255, 0.25);
}
.field .help {
  font-size: 0.8rem; color: var(--text-dim);
}
.field .error {
  font-size: 0.85rem;
  color: var(--danger);
  font-weight: 600;
}
.newsletter .submit-row {
  display: flex; align-items: end; gap: 8px;
}
.newsletter-status {
  font-size: 0.9rem;
  margin-top: 12px;
  color: var(--success);
  font-weight: 600;
  min-height: 1.5em;
}

/* Footer */
.site-footer {
  padding: 64px 0 24px;
  background: #07090b;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 1fr;
  gap: 36px;
  margin-bottom: 48px;
}
.footer-grid h4 {
  font-size: 0.85rem;
