  color-scheme: dark;
  --bg: #0b0d10;
  --bg-elev: #14171c;
  --bg-elev-2: #1b1f26;
  --border: #2a2f38;
  --border-strong: #3a414d;
  --text: #f1f3f6;
  --text-muted: #a3acba;
  --text-dim: #7b8696;
  --accent: #ffb347;
  --accent-strong: #ffc168;
  --accent-ink: #1a1205;
  --danger: #ef4444;
  --danger-strong: #dc2626;
  --success: #4ade80;
  --focus: #8ab4ff;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow: 0 8px 30px rgba(0, 0, 0, 0.45);
  --maxw: 1240px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }

a { color: inherit; }

/* Focus */
:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100px;
  left: 16px;
  background: var(--accent);
  color: var(--accent-ink);
  padding: 10px 16px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  z-index: 1000;
  text-decoration: none;
}
.skip-link:focus {
  top: 12px;
}

/* Layout */
.container {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 24px;
}

/* Top promo bar */
.promo-bar {
  background: linear-gradient(90deg, #1a1208, #2a1d0a);
  color: var(--accent-strong);
  text-align: center;
  font-size: 0.875rem;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border);
  letter-spacing: 0.02em;
}
.promo-bar strong { color: #fff; }

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(11, 13, 16, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}
.header-inner {
  display: flex;
  align-items: center;
  gap: 32px;
  padding: 16px 24px;
  max-width: var(--maxw);
  margin: 0 auto;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  font-size: 1.25rem;
  letter-spacing: 0.06em;
  text-decoration: none;
  color: var(--text);
}
.brand-mark {
  width: 32px; height: 32px;
  display: inline-grid; place-items: center;
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 8px;
  font-weight: 900;
}

.primary-nav {
  flex: 1;
}
.primary-nav ul {
  display: flex;
  gap: 6px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.primary-nav a {
  display: inline-block;
  padding: 8px 14px;
  border-radius: 8px;
  text-decoration: none;
  color: var(--text-muted);
  font-weight: 500;
  font-size: 0.95rem;
}
.primary-nav a:hover {
  color: var(--text);
  background: var(--bg-elev);
}
.primary-nav a[aria-current="page"] {
  color: var(--text);
  background: var(--bg-elev);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}
.icon-btn {
  appearance: none;
  background: transparent;
  border: 1px solid transparent;
  color: var(--text);
  width: 40px; height: 40px;
  border-radius: 10px;
  display: inline-grid; place-items: center;
  cursor: pointer;
  position: relative;
}
.icon-btn:hover { background: var(--bg-elev); border-color: var(--border); }
.icon-btn svg { width: 20px; height: 20px; }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
