  padding: 6px 12px;
  border-radius: 999px;
  border: 1px solid rgba(255, 179, 71, 0.25);
}
.hero h1 {
  font-size: clamp(2.25rem, 5vw, 4rem);
  line-height: 1.05;
  letter-spacing: -0.02em;
  margin: 20px 0 16px;
  font-weight: 800;
}
.hero h1 .accent { color: var(--accent-strong); font-style: italic; font-weight: 800; }
.hero p.lead {
  color: var(--text-muted);
  font-size: 1.125rem;
  max-width: 52ch;
  margin: 0 0 32px;
}
.hero-ctas {
  display: flex; gap: 12px; flex-wrap: wrap;
}
.btn {
  appearance: none;
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 14px 22px;
  font-weight: 700;
  font-size: 0.95rem;
  cursor: pointer;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: inherit;
}
.btn-primary {
  background: var(--accent);
  color: var(--accent-ink);
}
.btn-primary:hover { background: var(--accent-strong); }
.btn-secondary {
  background: transparent;
  color: var(--text);
  border-color: var(--border-strong);
}
.btn-secondary:hover { background: var(--bg-elev); border-color: var(--text-dim); }

.hero-stats {
  display: flex;
  gap: 36px;
  margin-top: 48px;
  padding-top: 28px;
  border-top: 1px solid var(--border);
}
.hero-stats div { min-width: 0; }
.hero-stats .num {
  font-size: 1.75rem; font-weight: 800; color: var(--text);
  letter-spacing: -0.02em;
}
.hero-stats .lbl {
  font-size: 0.85rem; color: var(--text-dim);
  text-transform: uppercase; letter-spacing: 0.1em;
}

.hero-art {
  position: relative;
  aspect-ratio: 4/5;
  border-radius: 24px;
  overflow: hidden;
  background: linear-gradient(135deg, #1f2530, #0f1216);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
}
.hero-art img {
  width: 100%; height: 100%; object-fit: cover;
}
.hero-badge {
  position: absolute;
  bottom: 20px; left: 20px;
  background: rgba(11, 13, 16, 0.75);
  backdrop-filter: blur(10px);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius);
  padding: 14px 16px;
  display: flex; gap: 12px; align-items: center;
  max-width: 80%;
}
.hero-badge .dot { width: 10px; height: 10px; background: var(--success); border-radius: 50%; box-shadow: 0 0 10px var(--success); }
.hero-badge strong { display: block; font-size: 0.95rem; }
.hero-badge span { color: var(--text-muted); font-size: 0.8rem; }

/* Section */
section.block {
  padding: 80px 0;
  border-bottom: 1px solid var(--border);
}
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 36px;
  flex-wrap: wrap;
}
.section-head h2 {
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  margin: 8px 0 0;
}
.section-head p {
  color: var(--text-muted);
  margin: 0;
  max-width: 50ch;
}
.section-head .head-link {
  color: var(--accent-strong);
  text-decoration: none;
  font-weight: 600;
  font-size: 0.95rem;
  white-space: nowrap;
}
.section-head .head-link:hover { text-decoration: underline; }

/* Category chips */
.chip-row {
  display: flex; gap: 10px; flex-wrap: wrap;
  margin-bottom: 28px;
}
.chip {
  appearance: none;
  background: var(--bg-elev);
  color: var(--text-muted);
  border: 1px solid var(--border);
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
}
.chip:hover { color: var(--text); border-color: var(--border-strong); }
.chip[aria-pressed="true"] {
  background: var(--accent);
  color: var(--accent-ink);
  border-color: var(--accent);
}

/* Product grid */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.product-card {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform 0.2s ease, border-color 0.2s ease;
}
.product-card:hover {
  transform: translateY(-3px);
  border-color: var(--border-strong);
}
.product-media {
  position: relative;
  aspect-ratio: 1/1;
  background: #0f1216;
  overflow: hidden;
}
.product-media img {
  width: 100%; height: 100%; object-fit: cover;
  transition: transform 0.5s ease;
}
.product-card:hover .product-media img { transform: scale(1.05); }
.tag {
  position: absolute; top: 12px; left: 12px;
  font-size: 0.7rem; font-weight: 800;
  text-transform: uppercase; letter-spacing: 0.08em;
  padding: 5px 9px; border-radius: 6px;
  background: var(--bg);
  color: var(--text);
  border: 1px solid var(--border-strong);
}
.tag.sale { background: #b91c1c; color: #fff; border-color: #b91c1c; }
.tag.new { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
.wishlist-btn {
  position: absolute; top: 10px; right: 10px;
  width: 36px; height: 36px;
  border-radius: 50%;
  border: 1px solid var(--border-strong);
  background: rgba(11, 13, 16, 0.7);
  color: var(--text);
  cursor: pointer;
  display: grid; place-items: center;
  backdrop-filter: blur(6px);
}
.wishlist-btn:hover { color: var(--accent); }
.wishlist-btn[aria-pressed="true"] { color: var(--accent); border-color: var(--accent); }
.wishlist-btn svg { width: 18px; height: 18px; }

.product-body {
  padding: 16px;
  display: flex; flex-direction: column; gap: 6px;
  flex: 1;
}
.product-cat {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-dim);
}
.product-name {
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
  color: var(--text);
}
.product-name a {
  text-decoration: none;
  color: inherit;
}
.product-name a:hover { color: var(--accent-strong); }
.product-rating {
  display: flex; align-items: center; gap: 6px;
  font-size: 0.85rem;
  color: var(--text-muted);
}
.stars { color: var(--accent); letter-spacing: 1px; }
.product-foot {
  display: flex; align-items: center; justify-content: space-between;
  margin-top: auto;
  padding-top: 12px;
}
.price {
  display: flex; align-items: baseline; gap: 8px;
}
.price .now { font-weight: 800; font-size: 1.1rem; }
.price .was {
  color: var(--text-dim);
  text-decoration: line-through;
  font-size: 0.9rem;
}
.add-btn {
  appearance: none;
  background: var(--bg-elev-2);
  border: 1px solid var(--border-strong);
  color: var(--text);
  width: 36px; height: 36px;
  border-radius: 8px;
  cursor: pointer;
  display: grid; place-items: center;
  font-family: inherit;
}
.add-btn:hover {
  background: var(--accent);
  color: var(--accent-ink);
  border-color: var(--accent);
}
.add-btn svg { width: 18px; height: 18px; }

/* Deals */
.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 24px;
}
.deal-card {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  border: 1px solid var(--border);
  min-height: 320px;
  display: flex; flex-direction: column;
  justify-content: flex-end;
  padding: 32px;
  isolation: isolate;
  background: var(--bg-elev);
}
.deal-card .bg {
  position: absolute; inset: 0; z-index: -2;
  background-size: cover; background-position: center;
}
.deal-card::after {
  content: "";
  position: absolute; inset: 0; z-index: -1;
  background: linear-gradient(180deg, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.85) 100%);
}
.deal-featured { min-height: 460px; }
.deal-card .eyebrow { background: rgba(11,13,16,0.6); color: var(--accent-strong); border-color: rgba(255,179,71,0.4); }
.deal-card h3 {
  font-size: clamp(1.5rem, 2.5vw, 2.25rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  margin: 12px 0 8px;
  max-width: 22ch;
}
.deal-card p {
  color: var(--text-muted);
  margin: 0 0 20px;
  max-width: 40ch;
}
.deal-stack {
  display: flex; flex-direction: column; gap: 24px;
}
.deal-stack .deal-card { min-height: 218px; padding: 24px; }
.deal-stack .deal-card h3 { font-size: 1.35rem; }

/* Countdown */
.countdown {
  display: flex; gap: 10px;
  margin-bottom: 20px;
}
.countdown div {
  background: rgba(11,13,16,0.7);
  border: 1px solid var(--border-strong);
  border-radius: 10px;
  padding: 8px 12px;
  min-width: 60px;
  text-align: center;
}
.countdown .v {
  display: block;
  font-weight: 800; font-size: 1.25rem;
  font-variant-numeric: tabular-nums;
}
.countdown .l {
  display: block;
  font-size: 0.65rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-dim);
}

/* Editorial */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
