function Countdown({ deadline }) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  const diff = Math.max(0, deadline - now);
  const h = Math.floor(diff / 3600000);
  const m = Math.floor((diff % 3600000) / 60000);
  const s = Math.floor((diff % 60000) / 1000);
  const pad = (n) => String(n).padStart(2, "0");
  return (
    <div
      className="countdown"
      role="timer"
      aria-live="off"
      aria-label={`Offer ends in ${h} hours ${m} minutes`}
    >
      <div><span className="v">{pad(h)}</span><span className="l">Hours</span></div>
      <div><span className="v">{pad(m)}</span><span className="l">Minutes</span></div>
      <div><span className="v">{pad(s)}</span><span className="l">Seconds</span></div>
    </div>
  );
}

