function Newsletter() {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [status, setStatus] = useState("");
  const onSubmit = (e) => {
    e.preventDefault();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setError("Please enter a valid email address.");
      setStatus("");
      return;
    }
    setError("");
    setStatus(`Thanks — we'll send the next drop to ${email}.`);
    setEmail("");
  };
  return (
    <section className="block" aria-labelledby="newsletter-title">
      <div className="container">
