function App() {
  const [wishlist, setWishlist] = useState(new Set());
  const [cart, setCart] = useState([]);
  const [toast, setToast] = useState("");
  const toastTimer = useRef(null);

  const onWishlist = (id) => {
    setWishlist((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };
  const onAdd = (id) => {
    setCart((c) => [...c, id]);
    const product = PRODUCTS.find((p) => p.id === id);
    setToast(`Added "${product.name}" to cart.`);
    clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(""), 3000);
  };

  return (
    <>
      <a className="skip-link" href="#main">Skip to main content</a>
      <PromoBar />
      <Header cartCount={cart.length} />
      <main id="main">
        <Hero />
        <FeaturedProducts wishlist={wishlist} onWishlist={onWishlist} onAdd={onAdd} />
        <Deals />
        <Editorial />
        <Newsletter />
      </main>
      <Footer />
      <div
        role="status"
        aria-live="polite"
        style={{
          position: "fixed", bottom: 24, left: "50%", transform: "translateX(-50%)",
          background: "#1b1f26", border: "1px solid #3a414d", color: "#fff",
          padding: toast ? "12px 18px" : 0, borderRadius: 10,
          opacity: toast ? 1 : 0, pointerEvents: "none",
          transition: "opacity .2s ease", zIndex: 100,
          fontSize: "0.9rem", fontWeight: 600,
          maxWidth: "90vw",
        }}
      >
        {toast}
      </div>
    </>
  );
}

